liquid:
{%- assign valid = true -%}
{%- assign inputs = nil -%}
{%- assign selected = '' | split: '' -%}
{%- assign hasInputs = apiEaseParameters | has_key: 'liquidParams' -%}
{%- if hasInputs -%}
  {%- assign inputs = apiEaseParameters.liquidParams -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs | has_key: 'variants' -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs.variants | is_type: 'array' -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs | has_key: 'expectedSku' -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs.expectedSku | is_type: 'string' -%}
{%- endif -%}
{%- if valid -%}
  {%- if inputs.expectedSku == '' -%}{%- assign valid = false -%}{%- endif -%}
{%- endif -%}
{%- assign error = 'variants must be an array and expectedSku must be a nonempty string; both fields are required.' -%}
{%- if valid -%}
  {%- for item in inputs.variants -%}
    {%- assign valid = item | has_key: 'sku' -%}
    {%- assign error = 'Each variants item must be an object with a valid sku field.' -%}
    {%- if valid -%}
      {%- call {"requestId":"match-exact-sku","liquidParamsEmbedded":{"candidateSku":{{ item.sku | json }},"expectedSku":{{ inputs.expectedSku | json }}}} as matcherResult -%}
      {%- assign error = 'The match-exact-sku call failed or returned an unusable result.' -%}
      {%- assign valid = matcherResult | has_key: 'status' -%}
      {%- if valid -%}
        {%- assign valid = matcherResult.status | is_type: 'integer' -%}
      {%- endif -%}
      {%- if valid -%}
        {%- if matcherResult.status < 200 or matcherResult.status >= 300 -%}{%- assign valid = false -%}{%- endif -%}
      {%- endif -%}
      {%- if valid -%}
        {%- assign valid = matcherResult | has_key: 'data' -%}
      {%- endif -%}
      {%- if valid -%}
        {%- assign hasSuccess = matcherResult.data | has_key: 'success' -%}
        {%- assign hasMatches = matcherResult.data | has_key: 'matches' -%}
        {%- assign hasError = matcherResult.data | has_key: 'error' -%}
        {%- unless hasSuccess and hasMatches and hasError -%}{%- assign valid = false -%}{%- endunless -%}
      {%- endif -%}
      {%- if valid -%}
        {%- assign successIsBoolean = matcherResult.data.success | is_type: 'boolean' -%}
        {%- assign matchesIsBoolean = matcherResult.data.matches | is_type: 'boolean' -%}
        {%- assign errorIsNull = matcherResult.data.error | is_type: 'null' -%}
        {%- unless successIsBoolean and matchesIsBoolean and errorIsNull and matcherResult.data.success == true -%}{%- assign valid = false -%}{%- endunless -%}
      {%- endif -%}
      {%- if valid -%}
        {%- if matcherResult.data.matches -%}
          {%- assign singleton = inputs.variants | slice: forloop.index0, 1 -%}
          {%- assign selected = selected | concat: singleton -%}
        {%- endif -%}
      {%- endif -%}
    {%- endif -%}
    {%- unless valid -%}{%- break -%}{%- endunless -%}
  {%- endfor -%}
{%- endif -%}
{%- if valid -%}
{"success":true,"variants":{{ selected | json }},"error":null}
{%- else -%}
{"success":false,"variants":[],"error":{{ error | json }}}
{%- endif -%}
